import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.iXqqCa-C.js";const i="/images/messages-layout.webp",o="/images/misskey-notifications.webp",u=JSON.parse('{"title":"消息与通知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/messages.md","filePath":"guide/messages.md","lastUpdated":1793501934000}'),s={name:"guide/messages.md"};function h(l,t,n,c,b,m){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="消息与通知" tabindex="-1">消息与通知 <a class="header-anchor" href="#消息与通知" aria-label="Permalink to &quot;消息与通知&quot;">​</a></h1><h2 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to &quot;消息&quot;">​</a></h2><p>侧栏「消息」进入消息页，私信、群聊和智能体会话都在这里。</p><h3 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h3><p><img src="'+i+'" alt="消息页面"></p><table tabindex="0"><thead><tr><th>标签页</th><th>内容</th></tr></thead><tbody><tr><td>首页</td><td>发起新聊天、搜索消息、查看全部聊天记录（私信、群聊与智能体会话）</td></tr><tr><td>私信</td><td>仅显示与用户的一对一私信列表</td></tr><tr><td>智能体</td><td>所有智能体会话列表</td></tr><tr><td>邀请</td><td>收到的群聊邀请</td></tr><tr><td>已加入的群聊</td><td>已加入的群聊</td></tr><tr><td>已创建的群聊</td><td>自己创建的群聊</td></tr></tbody></table><h3 id="私信" tabindex="-1">私信 <a class="header-anchor" href="#私信" aria-label="Permalink to &quot;私信&quot;">​</a></h3><ul><li>与其他用户一对一聊天。</li><li><strong>引用回复</strong>：右键消息选择「引用」，输入框上方会显示引用预览；被引用的消息可点击跳转定位。</li><li><strong>消息搜索</strong>：在首页或聊天室内搜索，点击结果直接定位到目标消息并高亮。</li><li><strong>举报</strong>：长按或右键对方消息选择「举报」，举报内容会自动附上该消息链接。</li></ul><h3 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h3><p>可以创建群聊并邀请其他用户，也可以搜索公开群聊直接加入。收到邀请、被移出或被禁言时会收到通知。</p><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><p>通知页集中显示与你相关的动态。</p><p><img src="'+o+'" alt="通知"></p><h3 id="标签页" tabindex="-1">标签页 <a class="header-anchor" href="#标签页" aria-label="Permalink to &quot;标签页&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标签页</th><th>内容</th></tr></thead><tbody><tr><td>全部</td><td>所有通知，可按类型筛选</td></tr><tr><td>提到我的</td><td>@你的帖子</td></tr><tr><td>私信</td><td>可见范围为「指定用户」且指定了你的帖子</td></tr></tbody></table><h3 id="通知类型" tabindex="-1">通知类型 <a class="header-anchor" href="#通知类型" aria-label="Permalink to &quot;通知类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>类型</th></tr></thead><tbody><tr><td>帖子与互动</td><td>关注、收到关注请求、关注请求已通过、提及、回复、转发、引用、回应、问卷调查结束、关注用户的新帖子</td></tr><tr><td>定时发帖</td><td>定时发送成功、定时发送失败</td></tr><tr><td>消息</td><td>私信、群聊邀请、新成员加入群聊、被移出群聊、被禁言 / 解除禁言</td></tr><tr><td>智能体</td><td>智能体消息、<a href="/guide/agent/proactive">主动消息</a>、角色审核通过 / 未通过、模型上报已处理、角色或会话封禁变更</td></tr><tr><td>账号</td><td>取得成就、授予角色、导出完成、登录、创建访问令牌、关联应用的通知</td></tr></tbody></table><p>每种类型的接收范围在「设置 → 通知」中调整，见<a href="/guide/misskey/settings-privacy#通知">设置与隐私</a>。</p>',18)])])}const _=a(s,[["render",h]]);export{u as __pageData,_ as default};
